describe('Multiple File Upload', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should successfully upload multiple files at once', () => {
    // Create mock files
    const file1 = new File(['content of file 1'], 'document1.pdf', { type: 'application/pdf' });
    const file2 = new File(['content of file 2'], 'image.png', { type: 'image/png' });
    const file3 = new File(['content of file 3'], 'spreadsheet.xlsx', { type: 'application/vnd.openxmlformats-spreadsheet' });

    // Intercept the upload API endpoint
    cy.intercept('POST', '/api/files/upload').as('uploadFiles');

    // Upload multiple files
    cy.get('[data-testid="file-input"]').selectFile([file1, file2, file3]);

    // Verify file names appear in the upload queue
    cy.get('[data-testid="file-list"]').should('contain', 'document1.pdf');
    cy.get('[data-testid="file-list"]').should('contain', 'image.png');
    cy.get('[data-testid="file-list"]').should('contain', 'spreadsheet.xlsx');

    // Click upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for API response
    cy.wait('@uploadFiles').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.response.body).to.have.property('success', true);
    });

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Files uploaded successfully');

    // Verify uploaded files are listed in the results
    cy.get('[data-testid="uploaded-files-list"]').should('contain', 'document1.pdf');
    cy.get('[data-testid="uploaded-files-list"]').should('contain', 'image.png');
    cy.get('[data-testid="uploaded-files-list"]').should('contain', 'spreadsheet.xlsx');
  });

  it('should handle file upload with invalid file types and display error messages', () => {
    // Create mock files with invalid types
    const invalidFile1 = new File(['invalid content'], 'script.js', { type: 'text/javascript' });
    const invalidFile2 = new File(['invalid content'], 'exe_file', { type: 'application/x86-64-win32-exe' });

    // Intercept the upload API endpoint
    cy.intercept('POST', '/api/files/upload').as('uploadFiles');

    // Upload invalid files
    cy.get('[data-testid="file-input"]').selectFile([invalidFile1, invalidFile2]);

    // Verify file names appear in the upload queue
    cy.get('[data-testid="file-list"]').should('contain', 'script.js');
    cy.get('[data-testid="file-list"]').should('contain', 'exe_file');

    // Click upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for API response
    cy.wait('@uploadFiles').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
      expect(interception.response.body).to.have.property('success', false);
      expect(interception.response.body).to.have.property('errors');
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid file type');

    // Verify uploaded files are not in the success list
    cy.get('[data-testid="uploaded-files-list"]').should('not.exist');

    // Verify error details are shown for each file
    cy.get('[data-testid="file-error-script.js"]').should('be.visible').should('contain', 'Invalid file type');
    cy.get('[data-testid="file-error-exe_file"]').should('be.visible').should('contain', 'Invalid file type');
  });
});
